def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))

    # If no budget, bid 0
    if budget <= 0:
        return 0.0

    alive_opponents = []
    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            if prev and prev.get('bid') is not None:
                try:
                    yesterday_bids.append(float(prev['bid']))
                except Exception:
                    pass

    # Baseline: bid enough to secure water when possible, but undercut heavy bidders.
    # Supply bands: higher supply -> more likely competition, so bid slightly higher.
    if supply >= 21:
        target = DAILY_SALARY * 0.95  # 66.5
    elif supply >= 18:
        target = DAILY_SALARY * 0.75  # 52.5
    else:
        target = DAILY_SALARY * 0.60  # 42.0

    # React to yesterday's pressure: if someone bid extremely high, we must match more.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # Opponents in the trace bid around 130+; if that happens again, we avoid full matching
        # but increase if my HP is at risk.
        if highest_prev_bid >= DAILY_SALARY * 1.6:  # ~112
            if hp <= 3:
                target = max(target, DAILY_SALARY * 1.05)  # 73.5
            else:
                target = max(target, DAILY_SALARY * 0.85)  # 59.5
        elif highest_prev_bid >= DAILY_SALARY * 1.0:  # ~70
            if hp <= 2:
                target = max(target, DAILY_SALARY * 0.95)
            else:
                target = max(target, DAILY_SALARY * 0.75)

    # If my HP is low, bid more to prevent death.
    if hp <= 2.0:
        target = max(target, DAILY_SALARY * 1.15)  # 80.5
    elif hp <= 4.0:
        target = max(target, DAILY_SALARY * 0.95)  # 66.5

    # Budget cap: never exceed budget.
    bid = min(budget, target)

    # Ensure non-negative.
    if bid < 0:
        bid = 0.0

    return float(bid)

