        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid > strong_prev:
                strong_prev = float(bid)
        if opp.get('budget', 0) < DAILY_SALARY * 0.8 or opp.get('hp', 0) <= 3:
            weak_or_broke += 1
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 0) <= 2:
            urgent_opp += 1

    if not alive:
        return float(min(budget, 20.0))

    scarcity = competitors - slots

    if hp <= 2 or no_water_days >= 2:
        bid = max(78.0, strong_prev + 2.0)
    elif hp <= 4 or no_water_days >= 1:
        if scarcity >= 2:
            bid = max(68.0, strong_prev + 1.5)
        else:
            bid = max(52.0, strong_prev * 0.75)
