    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_yesterday_bid = sum(yesterday_bids) / len(yesterday_bids)
    else:
        avg_yesterday_bid = 130.0

    # Desperate condition
    if hp <= 3 or no_water_days > 0:
        if budget >= DAILY_SALARY * 0.8:
            return min(budget, DAILY_SALARY * 0.85)
        else:
            return min(budget, DAILY_SALARY * 0.95)

    # Normal bidding: save money, undercut opponents
    base_bid = max(DAILY_SALARY * 0.2, avg_yesterday_bid * 0.5)
    if hp >= 8:
        bid = min(budget, base_bid)
    elif hp >= 5:
        bid = min(budget, base_bid * 1.3)
    else:
        bid = min(budget, base_bid * 1.6)

    # Ensure bid is within reasonable range
    bid = min(budget, max(0, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10
    MIN_HP_THRESHOLD = 3

    supply = day_context['supply']
    current_day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)
    num_active_players = num_alive_opponents + 1

    if num_active_players == 1:
        return min(my_budget, WATER_REQ * 0.1)

    num_can_get_water = int(supply // WATER_REQ)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.5

    if num_can_get_water >= num_active_players:
        base_bid = DAILY_SALARY * 0.3
    elif num_can_get_water < num_active_players:
        shortage_ratio = (num_active_players - num_can_get_water) / num_active_players
        base_bid = DAILY_SALARY * (0.5 + 0.4 * shortage_ratio)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid > DAILY_SALARY * 0.8:
            base_bid = max(base_bid, highest_prev_bid + 5)
        elif highest_prev_bid > DAILY_SALARY * 0.5:
            base_bid = max(base_bid, highest_prev_bid + 1)
        else:
            base_bid = max(base_bid, highest_prev_bid + 1)

    if my_hp <= MIN_HP_THRESHOLD:
        base_bid = max(base_bid, DAILY_SALARY * 0.95)
    elif my_hp >= EPISODE_DAYS - current_day + 1:
        if current_day < EPISODE_DAYS * 0.7 and num_can_get_water >= num_active_players:
            base_bid = min(base_bid, DAILY_SALARY * 0.4)

    if current_day >= EPISODE_DAYS - 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)

    final_bid = min(my_budget, max(WATER_REQ * 0.1, base_bid))

    if my_hp == 1:
        final_bid = my_budget
    elif my_hp == 0:
        return 0.0

    return final_bid

